[{"order":1,"type":"heading","text":"Dependency Injection with Hilt and Dagger in Android (Kotlin)"},{"order":2,"type":"paragraph","text":"Dependency Injection (DI) is a software design pattern that implements inversion of control for resolving dependencies. In Android development, Hilt is the standard library recommended by Google for implementing DI. Built on top of Dagger, Hilt significantly reduces the boilerplate of manual dependency injection in your app."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"To use Hilt in your Android project, you need to add the necessary dependencies and plugins to your Gradle files. First, add the Hilt Android plugin to your root build.gradle.kts file."},{"order":5,"type":"code","text":"plugins {
    id("com.google.dagger.hilt.android") version "2.48" apply false
}"},{"order":6,"type":"paragraph","text":"Next, apply the plugin and add the dependencies in your app-level build.gradle.kts file."},{"order":7,"type":"code","text":"plugins {
    id("com.android.application")
    id("org.jetbrains.kotlin.android")
    id("kotlin-kapt")
    id("com.google.dagger.hilt.android")
}

dependencies {
    implementation("com.google.dagger:hilt-android:2.48")
    kapt("com.google.dagger:hilt-compiler:2.48")
}"},{"order":8,"type":"subheading","text":"Application Class Setup"},{"order":9,"type":"paragraph","text":"Every app that uses Hilt must contain an Application class annotated with '@HiltAndroidApp'. This triggers Hilt's code generation, including a base class for your application that serves as the application-level dependency container."},{"order":10,"type":"code","text":"@HiltAndroidApp
class MyApplication : Application() {
    // Application-level setup if needed
}"},{"order":11,"type":"subheading","text":"Injecting Dependencies into Android Activities"},{"order":12,"type":"paragraph","text":"To make dependencies available to Android classes like Activities and Fragments, use the '@AndroidEntryPoint' annotation. You can then use the '@Inject' annotation for field injection."},{"order":13,"type":"code","text":"@AndroidEntryPoint
class MainActivity : AppCompatActivity() {

    @Inject
    lateinit var analyticsService: AnalyticsService

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)
        analyticsService.trackEvent("MainActivity launched")
    }
}"},{"order":14,"type":"subheading","text":"Providing Instances with Hilt Modules"},{"order":15,"type":"paragraph","text":"Sometimes types cannot be constructor-injected (for example, if they are from an external library or require interface implementations). In these cases, use Hilt modules with the '@Module' and '@InstallIn' annotations."},{"order":16,"type":"code","text":"@Module
@InstallIn(SingletonComponent::class)
object AppModule {

    @Provides
    @Singleton
    vfun provideAnalyticsService(): AnalyticsService {
        return AnalyticsServiceImpl()
    }
}"},{"order":17,"type":"subheading","text":"Key Takeaways"},{"order":18,"type":"bullet_point","text":"@HiltAndroidApp sets up the root component for the application."},{"order":19,"type":"bullet_point","text":"@AndroidEntryPoint enables dependency injection for Android lifecycle classes."},{"order":20,"type":"bullet_point","text":"@Inject requests the dependency inside target classes."},{"order":21,"type":"bullet_point","text":"@Module and @Provides instruct Hilt on how to create instances of types that cannot be constructor-injected."}]
